["Vay canına! Houdini'nin sihirbazlık gösterisini izlemek gibiydi. İşinizin ustasısınız! Bu gece bana büyük iyilik yaptınız. Unutmayacağım."] = "VAY CANINA! HOUDİNİ'NİN SİHİRBAZLIK GÖSTERİSİNİ İZLEMEK GİBİYDİ. İŞİNİZİN USTASISINIZ! BU GECE BANA BÜYÜK İYİLİK YAPTINIZ. UNUTMAYACAĞIM.",
["Vay canına! Karşı binaya keskin nişancı yerleştirdiler! Başınızı eğin ve onu indirin!"] = "VAY CANINA! KARŞI BİNAYA KESKİN NİŞANCI YERLEŞTİRDİLER! BAŞINIZI EĞİN VE ONU İNDİRİN!",
["Vay canına! Kutuları C4'le tuzaklamışlar! Etkisiz hâle getirin!"] = "VAY CANINA! KUTULARI C4'LE TUZAKLAMIŞLAR! ETKİSİZ HÂLE GETİRİN!",
["Vay canına! O alev makinesi fena vuruyor! Wang işi ciddiye almış!"] = "VAY CANINA! O ALEV MAKİNESİ FENA VURUYOR! WANG İŞİ CİDDİYE ALMIŞ!",
["Vay canına! Wilson'ın duvarını delip geçtiler!"] = "VAY CANINA! WİLSON'IN DUVARINI DELİP GEÇTİLER!",
["Vay canına! Şansınız yaver gidiyor!"] = "VAY CANINA! ŞANSINIZ YAVER GİDİYOR!",
["Vay canına, kaynak lambası buldunuz. Artık kapıyı yakıp geçebiliriz."] = "VAY CANINA, KAYNAK LAMBASI BULDUNUZ. ARTIK KAPIYI YAKIP GEÇEBİLİRİZ.",
["Vay canına. Dağ işi, şartlara bakılırsa oldukça iyi gitti. Umarım uçak yolculuğuna hazırsınızdır. Locke’un bir Murkywater kargo uçağında \"yardım\" istediği başka bir işi var. Operasyonlarını berbat etmeye iyice kararlı görünüyor; bana da uyar. Yine de şüpheli bir şeye karşı gözünüzü açık tutun. Hâlâ sırtımıza bıçak saplamak için beklemediğine ikna olmuş değilim."] = "VAY CANINA. DAĞ İŞİ, ŞARTLARA BAKILIRSA OLDUKÇA İYİ GİTTİ. UMARIM UÇAK YOLCULUĞUNA HAZIRSINIZDIR. LOCKE’UN BİR MURKYWATER KARGO UÇAĞINDA \"YARDIM\" İSTEDİĞİ BAŞKA BİR İŞİ VAR. OPERASYONLARINI BERBAT ETMEYE İYİCE KARARLI GÖRÜNÜYOR; BANA DA UYAR. YİNE DE ŞÜPHELİ BİR ŞEYE KARŞI GÖZÜNÜZÜ AÇIK TUTUN. HÂLÂ SIRTIMIZA BIÇAK SAPLAMAK İÇİN BEKLEMEDİĞİNE İKNA OLMUŞ DEĞİLİM.",
["Vay eşeğin dayısı olayım, kasa dairesi bomboş amına koyayım! Sadece dolu olanları açın, tamam mı? Kesinlikle."] = "VAY EŞEĞİN DAYISI OLAYIM, KASA DAİRESİ BOMBOŞ AMINA KOYAYIM! SADECE DOLU OLANLARI AÇIN, TAMAM MI? KESİNLİKLE.",
["Vay vay vay, artık matkaplarınız çok hızlı!"] = "VAY VAY VAY, ARTIK MATKAPLARINIZ ÇOK HIZLI!",
["Vay vay vay, dördüncü silahşor kimmiş? Bu otuzbirci senin küçük kardeşin mi Dallas?"] = "VAY VAY VAY, DÖRDÜNCÜ SİLAHŞOR KİMMİŞ? BU OTUZBİRCİ SENİN KÜÇÜK KARDEŞİN Mİ DALLAS?",
["Vay! Bunu beklemiyordum. Kapı için bir şeyi var mıydı, bakın."] = "VAY! BUNU BEKLEMİYORDUM. KAPI İÇİN BİR ŞEYİ VAR MIYDI, BAKIN.",
["Vay! Commissar her neredeyse bunu duydu!"] = "VAY! COMMİSSAR HER NEREDEYSE BUNU DUYDU!",
["Vay! Ellerindeki en saf parti bu olmalı."] = "VAY! ELLERİNDEKİ EN SAF PARTİ BU OLMALI.",
["Vay! Fena kurşun izi dostum. Nerede yedin?"] = "VAY! FENA KURŞUN İZİ DOSTUM. NEREDE YEDİN?",
["Vay! Hayatımda bu kadar Domuzcuk Parası görmedim! Domuzcuk'la gerçekten bütünleşmişsiniz."] = "VAY! HAYATIMDA BU KADAR DOMUZCUK PARASI GÖRMEDİM! DOMUZCUK'LA GERÇEKTEN BÜTÜNLEŞMİŞSİNİZ.",
["Vay! Kamyonda Bulldozer var! İndirin onu! Bela bekliyorlarmış galiba."] = "VAY! KAMYONDA BULLDOZER VAR! İNDİRİN ONU! BELA BEKLİYORLARMIŞ GALİBA.",
["Vay! Millet? İyi misiniz? Dikkatli olun demiştim!"] = "VAY! MİLLET? İYİ MİSİNİZ? DİKKATLİ OLUN DEMİŞTİM!",
["Vay! Ona dikkat edin. Etrafa attığınız şey askerî patlayıcı."] = "VAY! ONA DİKKAT EDİN. ETRAFA ATTIĞINIZ ŞEY ASKERÎ PATLAYICI.",
["Vay! Vay vay vay vay vay!"] = "VAY! VAY VAY VAY VAY VAY!",
["Vay! Şimdi o Domuzcuk Parası'nı gerçekten uçuracaksınız!"] = "VAY! ŞİMDİ O DOMUZCUK PARASI'NI GERÇEKTEN UÇURACAKSINIZ!",
["Vay! Şu yere bakın! Buradan kaldırabileceğimiz ganimeti düşünün!"] = "VAY! ŞU YERE BAKIN! BURADAN KALDIRABİLECEĞİMİZ GANİMETİ DÜŞÜNÜN!",
["Vay, Commissar'ın burada bir sürü kokaini var ama gerçek bir Rus gibi yakıp yıkma taktiği uyguluyor. Yani malı yok ediyor. Çabuk ulaşmazsanız bir dünya ek geliri kaçırırsınız!"] = "VAY, COMMİSSAR'IN BURADA BİR SÜRÜ KOKAİNİ VAR AMA GERÇEK BİR RUS GİBİ YAKIP YIKMA TAKTİĞİ UYGULUYOR. YANİ MALI YOK EDİYOR. ÇABUK ULAŞMAZSANIZ BİR DÜNYA EK GELİRİ KAÇIRIRSINIZ!",
["Vay, SWAT'ların gelmesi uzun sürmedi. Zaten yoldalarmış demek."] = "VAY, SWAT'LARIN GELMESİ UZUN SÜRMEDİ. ZATEN YOLDALARMIŞ DEMEK.",
["Vay, bir patlama daha! Dikkat edin!"] = "VAY, BİR PATLAMA DAHA! DİKKAT EDİN!",
["Vay, bir sürü ışık birden gitti. Yukarıdaki donanımı düzeltin."] = "VAY, BİR SÜRÜ IŞIK BİRDEN GİTTİ. YUKARIDAKİ DONANIMI DÜZELTİN.",
["Vay, bir tür enerji silahına benziyor. Kapıyı patlatmak için kullanabiliriz. Doğru yöne çevirin yeter, dostlar."] = "VAY, BİR TÜR ENERJİ SİLAHINA BENZİYOR. KAPIYI PATLATMAK İÇİN KULLANABİLİRİZ. DOĞRU YÖNE ÇEVİRİN YETER, DOSTLAR.",
["Vay, bizi ekip bir gösteriye mi gittiniz diye düşünüyordum."] = "VAY, BİZİ EKİP BİR GÖSTERİYE Mİ GİTTİNİZ DİYE DÜŞÜNÜYORDUM.",
["Vay, bunu beklemiyordum. The Elephant'ta da mı vardı? Alıp çıkın, bunu sonra çözeriz, tamam mı?"] = "VAY, BUNU BEKLEMİYORDUM. THE ELEPHANT'TA DA MI VARDI? ALIP ÇIKIN, BUNU SONRA ÇÖZERİZ, TAMAM MI?",
["Vay, bunun içi değerli eşyalarla dolu olmalı! Vlad'ın bu işletmelerin parasını neden istediğini anlayabiliyorum..."] = "VAY, BUNUN İÇİ DEĞERLİ EŞYALARLA DOLU OLMALI! VLAD'IN BU İŞLETMELERİN PARASINI NEDEN İSTEDİĞİNİ ANLAYABİLİYORUM...",
["Vay, büyük ikramiye! Sağlam vurduk! O kamyon devre dışı. İşe koyulun!"] = "VAY, BÜYÜK İKRAMİYE! SAĞLAM VURDUK! O KAMYON DEVRE DIŞI. İŞE KOYULUN!",
["Vay, fena ter kokuyorsun, dostum. Son zamanlarda çok çalışıyorsun, ha?"] = "VAY, FENA TER KOKUYORSUN, DOSTUM. SON ZAMANLARDA ÇOK ÇALIŞIYORSUN, HA?",
["Vay, fena çarptı."] = "VAY, FENA ÇARPTI.",
["Vay, ganimetin bir kısmı o patlamada gitti. Şansımıza içeride daha var."] = "VAY, GANİMETİN BİR KISMI O PATLAMADA GİTTİ. ŞANSIMIZA İÇERİDE DAHA VAR.",
["Vay, güzel küçük bir kokain zulaları varmış. Bana sorarsanız alabilirsiniz."] = "VAY, GÜZEL KÜÇÜK BİR KOKAİN ZULALARI VARMIŞ. BANA SORARSANIZ ALABİLİRSİNİZ.",
["Vay, hey dostum..."] = "VAY, HEY DOSTUM...",
["Vay, hey! Böyle işimi nasıl yapayım? Halledin onları!"] = "VAY, HEY! BÖYLE İŞİMİ NASIL YAPAYIM? HALLEDİN ONLARI!",
["Vay, kapı canavar gibi. Cephanelikte onu kırmaya yardım edecek bir şey var mı bakın."] = "VAY, KAPI CANAVAR GİBİ. CEPHANELİKTE ONU KIRMAYA YARDIM EDECEK BİR ŞEY VAR MI BAKIN.",
["Vay, kocaman diş fırçasıymış... İstiyorum."] = "VAY, KOCAMAN DİŞ FIRÇASIYMIŞ... İSTİYORUM.",
["Vay, merhaba eski dostum. Uşakların bankamda istediğin şeyi buldu sanırım? Senin için başka ne yapabilirim?"] = "VAY, MERHABA ESKİ DOSTUM. UŞAKLARIN BANKAMDA İSTEDİĞİN ŞEYİ BULDU SANIRIM? SENİN İÇİN BAŞKA NE YAPABİLİRİM?",
["Vay, merhaba güzelim... Bain, dizüstü bilgisayarı buldum. Yakınlarda olmalı."] = "VAY, MERHABA GÜZELİM... BAIN, DİZÜSTÜ BİLGİSAYARI BULDUM. YAKINLARDA OLMALI.",
["Vay, müthiş patlamaydı! Polisler artık yolda, hızlı sürün!"] = "VAY, MÜTHİŞ PATLAMAYDI! POLİSLER ARTIK YOLDA, HIZLI SÜRÜN!",
["Vay, ne kaza ama!"] = "VAY, NE KAZA AMA!",
["Vay, o patlamada biraz ganimet kaybettik! Neyse, kaybedecek vakit yok! Kalan kiralık kasalara bakın."] = "VAY, O PATLAMADA BİRAZ GANİMET KAYBETTİK! NEYSE, KAYBEDECEK VAKİT YOK! KALAN KİRALIK KASALARA BAKIN.",
["Vay, pahalı tekneymiş. Powell denen adamda para var."] = "VAY, PAHALI TEKNEYMİŞ. POWELL DENEN ADAMDA PARA VAR.",
["Vay, polisler ağır takviye çağırıyor. Her an gelebilirler!"] = "VAY, POLİSLER AĞIR TAKVİYE ÇAĞIRIYOR. HER AN GELEBİLİRLER!",
["Vay, siz bayağı eğlencelisiniz. Buraya kadar uçan parçalar gördüm."] = "VAY, SİZ BAYAĞI EĞLENCELİSİNİZ. BURAYA KADAR UÇAN PARÇALAR GÖRDÜM.",
["Vay, ter kokuyorsun gringo. Son zamanlarda çok mu çalıştın?"] = "VAY, TER KOKUYORSUN GRİNGO. SON ZAMANLARDA ÇOK MU ÇALIŞTIN?",
["Vay, uzun sürmedi!"] = "VAY, UZUN SÜRMEDİ!",
["Vay, vay! Kumandalar tepki vermiyor!"] = "VAY, VAY! KUMANDALAR TEPKİ VERMİYOR!",
["Vay, vay, vay, vay!"] = "VAY, VAY, VAY, VAY!",
["Vay, şunlara bakın. Gerçek olamaz... Değil mi?"] = "VAY, ŞUNLARA BAKIN. GERÇEK OLAMAZ... DEĞİL Mİ?",
["Vay. Kazandım mı?"] = "VAY. KAZANDIM MI?",
["Vay. Ne olaydı ama. İyi misiniz? Eksik uzuv yok, değil mi?"] = "VAY. NE OLAYDI AMA. İYİ MİSİNİZ? EKSİK UZUV YOK, DEĞİL Mİ?",
["Vay. Ruslar bu taktiğe yakıp yıkma derdi. Çok saldırgan. Eminim Vlad teşekkür için size birer votka koyar."] = "VAY. RUSLAR BU TAKTİĞE YAKIP YIKMA DERDİ. ÇOK SALDIRGAN. EMİNİM VLAD TEŞEKKÜR İÇİN SİZE BİRER VOTKA KOYAR.",
["Vay. Yakından gerçekten küçükmüş."] = "VAY. YAKINDAN GERÇEKTEN KÜÇÜKMÜŞ.",
["Vay. İhtimal neydi ki? Evet, belki de pek yüksek değildi..."] = "VAY. İHTİMAL NEYDİ Kİ? EVET, BELKİ DE PEK YÜKSEK DEĞİLDİ...",
["Vay... Burası düşündüğümüzden büyükmüş. Aşağıda sizi epey iş bekliyor."] = "VAY... BURASI DÜŞÜNDÜĞÜMÜZDEN BÜYÜKMÜŞ. AŞAĞIDA SİZİ EPEY İŞ BEKLİYOR.",
["Vay... Harika gidiyorsunuz..."] = "VAY... HARİKA GİDİYORSUNUZ...",
["Vay... Kıl payıydı! Bu Ruslar gerçekten partilerinin basılmasını istemiyor."] = "VAY... KIL PAYIYDI! BU RUSLAR GERÇEKTEN PARTİLERİNİN BASILMASINI İSTEMİYOR.",
["Vay... Kıl payıydı... Bildiğim kadarıyla hâlâ iyiyiz."] = "VAY... KIL PAYIYDI... BİLDİĞİM KADARIYLA HÂLÂ İYİYİZ.",
["Vay... Sadece... Gerçekten çok iyi."] = "VAY... SADECE... GERÇEKTEN ÇOK İYİ.",
["Vay... peki. Durun! Buluc'un kasası... Bütün bağlantıları ve anlaşmaları içinde. Açabilirseniz elimizde bulunması iyi olur!"] = "VAY... PEKİ. DURUN! BULUC'UN KASASI... BÜTÜN BAĞLANTILARI VE ANLAŞMALARI İÇİNDE. AÇABİLİRSENİZ ELİMİZDE BULUNMASI İYİ OLUR!",
["Vazgeçmeyin! Burada bir yerde olmalı!"] = "VAZGEÇMEYİN! BURADA BİR YERDE OLMALI!",
["Vazgeçmeyin..."] = "VAZGEÇMEYİN...",
["Vazgeçtik; elinizdeki her şeyi alıyoruz!"] = "VAZGEÇTİK; ELİNİZDEKİ HER ŞEYİ ALIYORUZ!",
["Ve Daha Fazlasını Öğren"] = "VE DAHA FAZLASINI ÖĞREN",
["Ve Domuz Kumbara patlar!"] = "VE DOMUZ KUMBARA PATLAR!",
["Ve bum! O üst geçidi kullanamayacaklar."] = "VE BUM! O ÜST GEÇİDİ KULLANAMAYACAKLAR.",
["Ve gidiyoruz, dostlarım!"] = "VE GİDİYORUZ, DOSTLARIM!",
["Ve hop, kapıdan dışarı!"] = "VE HOP, KAPIDAN DIŞARI!",
["Ve içeri girdiniz!"] = "VE İÇERİ GİRDİNİZ!",
["Ve son. Pislik Yoldaş öldü. Helikopter geliyor. Bugün harika iş çıkardınız. The Dentist ve Hoxton size teşekkür edecek."] = "VE SON. PİSLİK YOLDAŞ ÖLDÜ. HELİKOPTER GELİYOR. BUGÜN HARİKA İŞ ÇIKARDINIZ. THE DENTIST VE HOXTON SİZE TEŞEKKÜR EDECEK.",
["Ve tahtaya bir oyuncu daha giriyor. Kento! Bain kaçıyor. Onu durdurur musun lütfen?"] = "VE TAHTAYA BİR OYUNCU DAHA GİRİYOR. KENTO! BAIN KAÇIYOR. ONU DURDURUR MUSUN LÜTFEN?",
["Ve tamam, güzel."] = "VE TAMAM, GÜZEL.",
["Ve yere serildiler. Tamam, bahse girerim kokain o kasada. Matkap vakti."] = "VE YERE SERİLDİLER. TAMAM, BAHSE GİRERİM KOKAİN O KASADA. MATKAP VAKTİ.",
["Ve Şimdi Bambaşka Bir Şey"] = "VE ŞİMDİ BAMBAŞKA BİR ŞEY",
["Ve..."] = "VE...",
["Ve... Alex istenen yükü bıraktı. Bir yerlere."] = "VE... ALEX İSTENEN YÜKÜ BIRAKTI. BİR YERLERE.",
["Ve... Banka artık karanlık. Aferin ekip. "] = "VE... BANKA ARTIK KARANLIK. AFERİN EKİP. ",
["Ve... Buldum! Rus dostumuz bir yerde... Bekleyin..."] = "VE... BULDUM! RUS DOSTUMUZ BİR YERDE... BEKLEYİN...",
["Ve... Evet, tatmin edici bir iş oldu! Bütün çantalar! Şimdi lütfen kendinizi kablolara bağlayıp yukarı, yanıma gelin de yüz yüze tanışalım!"] = "VE... EVET, TATMİN EDİCİ BİR İŞ OLDU! BÜTÜN ÇANTALAR! ŞİMDİ LÜTFEN KENDİNİZİ KABLOLARA BAĞLAYIP YUKARI, YANIMA GELİN DE YÜZ YÜZE TANIŞALIM!",
["Ve... Girdim! Harika. Şimdi bağlantıyı koruyun. Olabildiğince hızlıyım."] = "VE... GİRDİM! HARİKA. ŞİMDİ BAĞLANTIYI KORUYUN. OLABİLDİĞİNCE HIZLIYIM.",
["Ve... Harika. Elektrik şebekeleri zayıflıyor. Bir tane daha yapın."] = "VE... HARİKA. ELEKTRİK ŞEBEKELERİ ZAYIFLIYOR. BİR TANE DAHA YAPIN.",
["Ve... Yakaladım! Millet, yakaladım! Bazen kendime bile hayran kalıyorum."] = "VE... YAKALADIM! MİLLET, YAKALADIM! BAZEN KENDİME BİLE HAYRAN KALIYORUM.",
["Ve... açıl susam açıl!"] = "VE... AÇIL SUSAM AÇIL!",
["Ve... açıl susam açıl! Bravo dostlarım! Şimdi lütfen şu siktiğimin hava kilidine girin."] = "VE... AÇIL SUSAM AÇIL! BRAVO DOSTLARIM! ŞİMDİ LÜTFEN ŞU SİKTİĞİMİN HAVA KİLİDİNE GİRİN.",
["Ve... bam!"] = "VE... BAM!",
["Ve... başlıyoruz!"] = "VE... BAŞLIYORUZ!",
["Ve... buldum! Şimdi kodu panik odasının kapısında kullanın!"] = "VE... BULDUM! ŞİMDİ KODU PANİK ODASININ KAPISINDA KULLANIN!",
["Ve... büyük ikramiye! Moretta'nın iletişim frekansları dâhil teknik bilgileri. Harika iş! Şimdi en yakın telsizi arayın, kaptanla konuşalım."] = "VE... BÜYÜK İKRAMİYE! MORETTA'NIN İLETİŞİM FREKANSLARI DÂHİL TEKNİK BİLGİLERİ. HARİKA İŞ! ŞİMDİ EN YAKIN TELSİZİ ARAYIN, KAPTANLA KONUŞALIM.",
["Ve... depo açıldı. Anahtarlar sizi bekliyor."] = "VE... DEPO AÇILDI. ANAHTARLAR SİZİ BEKLİYOR.",
["Ve... gidiyoruz!"] = "VE... GİDİYORUZ!",
["Ve... harika! Kasa Dairesinin tavanı orada!"] = "VE... HARİKA! KASA DAİRESİNİN TAVANI ORADA!",
["Ve... havalandı! Muhteşem iş çıkardınız ekip!"] = "VE... HAVALANDI! MUHTEŞEM İŞ ÇIKARDINIZ EKİP!",
["Ve... işte!"] = "VE... İŞTE!",
["Ve... kilitli. Lanet olsun! Tamam. Sessiz kalın. Müdür oralarda bir yerdedir. Rehin alın. Bizi içeri sokabilir."] = "VE... KİLİTLİ. LANET OLSUN! TAMAM. SESSİZ KALIN. MÜDÜR ORALARDA BİR YERDEDİR. REHİN ALIN. BİZİ İÇERİ SOKABİLİR.",
["Ve... tamam! Gemi hareket ediyor. Sıkı durun millet, bu biraz sürecek! Öldürülmemeye çalışın."] = "VE... TAMAM! GEMİ HAREKET EDİYOR. SIKI DURUN MİLLET, BU BİRAZ SÜRECEK! ÖLDÜRÜLMEMEYE ÇALIŞIN.",
["Ve... tamamdır! Depo açıldı. Anahtarları alın."] = "VE... TAMAMDIR! DEPO AÇILDI. ANAHTARLARI ALIN.",
["Ve... tutturdum. Tutturdum! Tutturduğuma inanamıyorum."] = "VE... TUTTURDUM. TUTTURDUM! TUTTURDUĞUMA İNANAMIYORUM.",
["Ve... şimdi!"] = "VE... ŞİMDİ!",
["Veba Doktoru"] = "VEBA DOKTORU",
["Veee bitti! Sıradakine geçelim..."] = "VEEE BİTTİ! SIRADAKİNE GEÇELİM...",
["Veee bitti! Yepyeni gibi... Elveda sevgilim... Özleyeceğim seni... Seni seviyorum."] = "VEEE BİTTİ! YEPYENİ GİBİ... ELVEDA SEVGİLİM... ÖZLEYECEĞİM SENİ... SENİ SEVİYORUM.",
