["Vlad'ın dediği gibi... Kokain keçilerin içinde, keçiler de... şey, şehir merkezinin her yanına dağılmış. İzlerini sürün."] = "VLAD'IN DEDİĞİ GİBİ... KOKAİN KEÇİLERİN İÇİNDE, KEÇİLER DE... ŞEY, ŞEHİR MERKEZİNİN HER YANINA DAĞILMIŞ. İZLERİNİ SÜRÜN.",
["Vlad'ın gençliği gibi ama çok daha az ateş ediliyor. İnanılmaz, henüz kimse ölmedi."] = "VLAD'IN GENÇLİĞİ GİBİ AMA ÇOK DAHA AZ ATEŞ EDİLİYOR. İNANILMAZ, HENÜZ KİMSE ÖLMEDİ.",
["Vlad'ın itibarı yükselecek. Siz de bu işten güzel bir para alacaksınız."] = "VLAD'IN İTİBARI YÜKSELECEK. SİZ DE BU İŞTEN GÜZEL BİR PARA ALACAKSINIZ.",
["Vlad'ın işleri Gizlilik ve Açık Çatışma karışımıdır; her şeye hazır ol."] = "VLAD'IN İŞLERİ GİZLİLİK VE AÇIK ÇATIŞMA KARIŞIMIDIR; HER ŞEYE HAZIR OL.",
["Vlad'ın karısı çok sevinecek. Şimdi o şeyi oradan çıkarın."] = "VLAD'IN KARISI ÇOK SEVİNECEK. ŞİMDİ O ŞEYİ ORADAN ÇIKARIN.",
["Vlad'ın kayınbiraderi polislerden AVM'nin yükleme alanında saklandı. Görünüşe göre kokaini çeşitli kutulara gizledi. O kutular şimdi AVM'nin dört bir yanındaki mağazalara dağıtılmış. Bir de Santa Claus kostümü giyip votka çalmış ve sarhoş olmuş. Ne rezalet. Polisler sarhoş Santa'dan şüphelenip onu yakaladı. Onu kurtarmalı ve kokaini hangi kutulara koyduğunu hatırlayıp hatırlamadığını sormalısınız."] = "VLAD'IN KAYINBİRADERİ POLİSLERDEN AVM'NİN YÜKLEME ALANINDA SAKLANDI. GÖRÜNÜŞE GÖRE KOKAİNİ ÇEŞİTLİ KUTULARA GİZLEDİ. O KUTULAR ŞİMDİ AVM'NİN DÖRT BİR YANINDAKİ MAĞAZALARA DAĞITILMIŞ. BİR DE SANTA CLAUS KOSTÜMÜ GİYİP VOTKA ÇALMIŞ VE SARHOŞ OLMUŞ. NE REZALET. POLİSLER SARHOŞ SANTA'DAN ŞÜPHELENİP ONU YAKALADI. ONU KURTARMALI VE KOKAİNİ HANGİ KUTULARA KOYDUĞUNU HATIRLAYIP HATIRLAMADIĞINI SORMALISINIZ.",
["Vlad'ın kayınbiraderi polislerden alışveriş merkezinin yükleme alanına saklandı. Kokaini çeşitli kutulara gizlemiş. O kutular da artık merkezin her yanındaki dükkânlara dağılmış. Kendini Noel Baba kılığına sokup votka çalmış, sarhoş da olmuş. Ne rezalet. Polisler sarhoş Noel Baba'dan şüphelenip yakalamış. Onu kurtarın ve kokaini hangi kutulara koyduğunu hatırlıyor mu sorun."] = "VLAD'IN KAYINBİRADERİ POLİSLERDEN ALIŞVERİŞ MERKEZİNİN YÜKLEME ALANINA SAKLANDI. KOKAİNİ ÇEŞİTLİ KUTULARA GİZLEMİŞ. O KUTULAR DA ARTIK MERKEZİN HER YANINDAKİ DÜKKÂNLARA DAĞILMIŞ. KENDİNİ NOEL BABA KILIĞINA SOKUP VOTKA ÇALMIŞ, SARHOŞ DA OLMUŞ. NE REZALET. POLİSLER SARHOŞ NOEL BABA'DAN ŞÜPHELENİP YAKALAMIŞ. ONU KURTARIN VE KOKAİNİ HANGİ KUTULARA KOYDUĞUNU HATIRLIYOR MU SORUN.",
["Vlad'ın kayınbiraderi sağ salim döndü. Büyük ölçüde salim, ha? Güzel bir gizlilik gösterisiydi dostlarım."] = "VLAD'IN KAYINBİRADERİ SAĞ SALİM DÖNDÜ. BÜYÜK ÖLÇÜDE SALİM, HA? GÜZEL BİR GİZLİLİK GÖSTERİSİYDİ DOSTLARIM.",
["Vlad'ın kayınbiraderi sağ salim geri döndü, sayılır! Şu aptal heriflere Ukraynalı gangsterlerle uğraşılmayacağını gösterdik galiba, ha?"] = "VLAD'IN KAYINBİRADERİ SAĞ SALİM GERİ DÖNDÜ, SAYILIR! ŞU APTAL HERİFLERE UKRAYNALI GANGSTERLERLE UĞRAŞILMAYACAĞINI GÖSTERDİK GALİBA, HA?",
["Vlad'ın mallarını alın!"] = "VLAD'IN MALLARINI ALIN!",
