["İstihbarata göre USB bellek bir dolapta kilitli."] = "İSTİHBARATA GÖRE USB BELLEK BİR DOLAPTA KİLİTLİ.",
["İstihbarata göre oralarda bir yere tehlikeli kimyasallar yığmışlar. O engelde kullanabileceğiniz ne var bakın, tamam mı?"] = "İSTİHBARATA GÖRE ORALARDA BİR YERE TEHLİKELİ KİMYASALLAR YIĞMIŞLAR. O ENGELDE KULLANABİLECEĞİNİZ NE VAR BAKIN, TAMAM MI?",
["İstihbarata göre ordunun vagonları hareket sensörleriyle kaplı. Etrafta bir kontrol konsolu arayın, sonra o küçük bokları kapatmak için kullanın."] = "İSTİHBARATA GÖRE ORDUNUN VAGONLARI HAREKET SENSÖRLERİYLE KAPLI. ETRAFTA BİR KONTROL KONSOLU ARAYIN, SONRA O KÜÇÜK BOKLARI KAPATMAK İÇİN KULLANIN.",
["İstihbaratı almadan önce bizi durdurmalarını istemeyiz. Kasayı bulun, muhtemelen orada."] = "İSTİHBARATI ALMADAN ÖNCE BİZİ DURDURMALARINI İSTEMEYİZ. KASAYI BULUN, MUHTEMELEN ORADA.",
["İstihbaratı inceledim. Bu iş ilginç olacak. Destek seçeneklerine bakın ve hepsini iyice öğrenin. Bu adamın laboratuvarını, laboratuvarda da füzyon motorunu bulmak için içeri gizlice girmemiz gerekiyor."] = "İSTİHBARATI İNCELEDİM. BU İŞ İLGİNÇ OLACAK. DESTEK SEÇENEKLERİNE BAKIN VE HEPSİNİ İYİCE ÖĞRENİN. BU ADAMIN LABORATUVARINI, LABORATUVARDA DA FÜZYON MOTORUNU BULMAK İÇİN İÇERİ GİZLİCE GİRMEMİZ GEREKİYOR.",
["İstihbaratı inceledim. İlginç olacak. Destek seçeneklerine bakın, içlerini dışlarını iyice öğrenin. Gizlice girip adamın laboratuvarını, laboratuvarda da füzyon motorunu bulmalıyız."] = "İSTİHBARATI İNCELEDİM. İLGİNÇ OLACAK. DESTEK SEÇENEKLERİNE BAKIN, İÇLERİNİ DIŞLARINI İYİCE ÖĞRENİN. GİZLİCE GİRİP ADAMIN LABORATUVARINI, LABORATUVARDA DA FÜZYON MOTORUNU BULMALIYIZ.",
["İstihbaratı yakmalarına izin vermeyin. Tanrım!"] = "İSTİHBARATI YAKMALARINA İZİN VERMEYİN. TANRIM!",
["İstihbaratı yakmışlar gibi. Eli boş gitmemiz gerekecek!"] = "İSTİHBARATI YAKMIŞLAR GİBİ. ELİ BOŞ GİTMEMİZ GEREKECEK!",
["İstihbaratım PEOC girişinin tam yerini belirtmiyordu. Bir şey bulmaya çalışın. Gerekirse odayı altüst edin."] = "İSTİHBARATIM PEOC GİRİŞİNİN TAM YERİNİ BELİRTMİYORDU. BİR ŞEY BULMAYA ÇALIŞIN. GEREKİRSE ODAYI ALTÜST EDİN.",
["İstihbaratıma göre kütüphanenin yanında PEOC'a gizli bir giriş noktaları var. Oraya gidin."] = "İSTİHBARATIMA GÖRE KÜTÜPHANENİN YANINDA PEOC'A GİZLİ BİR GİRİŞ NOKTALARI VAR. ORAYA GİDİN.",
["İstihbaratımız doğru, konteynerin içinde."] = "İSTİHBARATIMIZ DOĞRU, KONTEYNERİN İÇİNDE.",
["İstihbaratımıza göre Kang genelde kumarhaneyi gözetliyormuş."] = "İSTİHBARATIMIZA GÖRE KANG GENELDE KUMARHANEYİ GÖZETLİYORMUŞ.",
["İstihbaratımıza göre bu araba pazarlama müdürüne ait. Onu dışarı çıkarmaya çalışıyorsanız arabanın alarmı işe yarar."] = "İSTİHBARATIMIZA GÖRE BU ARABA PAZARLAMA MÜDÜRÜNE AİT. ONU DIŞARI ÇIKARMAYA ÇALIŞIYORSANIZ ARABANIN ALARMI İŞE YARAR.",
["İstihbaratımıza göre kasa dairesi okuyucusunda Xun Kang'ın el izi kayıtlı, açılış şifresi ise Li Deng'de. Onları bul!"] = "İSTİHBARATIMIZA GÖRE KASA DAİRESİ OKUYUCUSUNDA XUN KANG'IN EL İZİ KAYITLI, AÇILIŞ ŞİFRESİ İSE Lİ DENG'DE. ONLARI BUL!",
["İstila"] = "İSTİLA",
["İstisnasız hepsi tamam! Harika!"] = "İSTİSNASIZ HEPSİ TAMAM! HARİKA!",
["İsveç kralı, Çinli bir tetikçinin kıyafetini giymek isteyen bir soyguncu olsaydı bunu seçebilirdi!"] = "İSVEÇ KRALI, ÇİNLİ BİR TETİKÇİNİN KIYAFETİNİ GİYMEK İSTEYEN BİR SOYGUNCU OLSAYDI BUNU SEÇEBİLİRDİ!",
["İsveçli mühendis Alfred Nobel dinamiti ve kayaları patlatmadaki etkisini keşfetti. Ama insanları patlatmadaki etkisini keşfeden, sarhoş maden arayıcısı Ol’ Kenneth oldu."] = "İSVEÇLİ MÜHENDİS ALFRED NOBEL DİNAMİTİ VE KAYALARI PATLATMADAKİ ETKİSİNİ KEŞFETTİ. AMA İNSANLARI PATLATMADAKİ ETKİSİNİ KEŞFEDEN, SARHOŞ MADEN ARAYICISI OL’ KENNETH OLDU.",
["İsviçre Peyniri"] = "İSVİÇRE PEYNİRİ",
["İsyancılar. Katiller. Vatanseverler. Hırsızlar. Amerikan tarihinde derin kökleri olan gerilla askerleri bushwhacker’ları herkes farklı tanımlıyordu. Bağımsızlık Savaşı’ndan İç Savaş’a kadar, kendilerine ait olanı korumak için dişleriyle tırnaklarıyla savaştılar. Sevsen de nefret etsen de Vahşi Batı’nın bir devinin doğuşundaki rollerini inkâr edemezsin: Jesse James’e silah kullanmayı onlar öğretti."] = "İSYANCILAR. KATİLLER. VATANSEVERLER. HIRSIZLAR. AMERİKAN TARİHİNDE DERİN KÖKLERİ OLAN GERİLLA ASKERLERİ BUSHWHACKER’LARI HERKES FARKLI TANIMLIYORDU. BAĞIMSIZLIK SAVAŞI’NDAN İÇ SAVAŞ’A KADAR, KENDİLERİNE AİT OLANI KORUMAK İÇİN DİŞLERİYLE TIRNAKLARIYLA SAVAŞTILAR. SEVSEN DE NEFRET ETSEN DE VAHŞİ BATI’NIN BİR DEVİNİN DOĞUŞUNDAKİ ROLLERİNİ İNKÂR EDEMEZSİN: JESSE JAMES’E SİLAH KULLANMAYI ONLAR ÖĞRETTİ.",
["İtibar seviyesi"] = "İTİBAR SEVİYESİ",
["İtibarla"] = "İTİBARLA",
["İtibarsız Olmak"] = "İTİBARSIZ OLMAK",
["İtibarı bu ayardan düşük olan oyuncular oyuna katılamaz. Bu değeri kendi mevcut itibarından yüksek ayarlayamazsın."] = "İTİBARI BU AYARDAN DÜŞÜK OLAN OYUNCULAR OYUNA KATILAMAZ. BU DEĞERİ KENDİ MEVCUT İTİBARINDAN YÜKSEK AYARLAYAMAZSIN.",
["İtibarın bu sunucuya katılmak için çok düşük."] = "İTİBARIN BU SUNUCUYA KATILMAK İÇİN ÇOK DÜŞÜK.",
["İtibarını Kaybetme"] = "İTİBARINI KAYBETME",
["İtiraf edeyim, bir yere bu kadar gürültülü girmeyeli uzun zaman oldu. Eğlenceli olacak!"] = "İTİRAF EDEYİM, BİR YERE BU KADAR GÜRÜLTÜLÜ GİRMEYELİ UZUN ZAMAN OLDU. EĞLENCELİ OLACAK!",
["İtiraf edeyim, biraz endişelenmiştim. Teşekkürler."] = "İTİRAF EDEYİM, BİRAZ ENDİŞELENMİŞTİM. TEŞEKKÜRLER.",
["İtiraf edeyim, bu kadar iyi gideceğini düşünmüştüm."] = "İTİRAF EDEYİM, BU KADAR İYİ GİDECEĞİNİ DÜŞÜNMÜŞTÜM.",
["İtiraf edin. Sizi otuzbirciler, o güzel İngiliz aksanımı özlediniz. Değil mi? Özlediniz mi? Otuzbirciler."] = "İTİRAF EDİN. SİZİ OTUZBİRCİLER, O GÜZEL İNGİLİZ AKSANIMI ÖZLEDİNİZ. DEĞİL Mİ? ÖZLEDİNİZ Mİ? OTUZBİRCİLER.",
["İvme "] = "İVME ",
["İyi Bir Vurgun"] = "İYİ BİR VURGUN",
["İyi Günler!"] = "İYİ GÜNLER!",
["İyi Müzik"] = "İYİ MÜZİK",
["İyi Olmak Güzel"] = "İYİ OLMAK GÜZEL",
["İyi Uçuşlar"] = "İYİ UÇUŞLAR",
["İyi adam, ha?"] = "İYİ ADAM, HA?",
["İyi adam. Kız da bu sayede silah kullanmayı bayağı öğrendi!"] = "İYİ ADAM. KIZ DA BU SAYEDE SİLAH KULLANMAYI BAYAĞI ÖĞRENDİ!",
["İyi akşamlar efendim."] = "İYİ AKŞAMLAR EFENDİM.",
["İyi akşamlar, ben Ajan Green. Bugünün şifresi yanlış görünüyor. Teyit etmem gerek."] = "İYİ AKŞAMLAR, BEN AJAN GREEN. BUGÜNÜN ŞİFRESİ YANLIŞ GÖRÜNÜYOR. TEYİT ETMEM GEREK.",
["İyi atış!"] = "İYİ ATIŞ!",
["İyi atış! Pekâlâ. Kokain o Kasada olmalı, delmeye başla."] = "İYİ ATIŞ! PEKÂLÂ. KOKAİN O KASADA OLMALI, DELMEYE BAŞLA.",
["İyi atışlar dostlarım. Anlaştığımız gibi C4'ü bırakıyorum."] = "İYİ ATIŞLAR DOSTLARIM. ANLAŞTIĞIMIZ GİBİ C4'Ü BIRAKIYORUM.",
["İyi avlar!"] = "İYİ AVLAR!",
["İyi başlangıç! Bir dahakine daha da ileri gidebilir misiniz?"] = "İYİ BAŞLANGIÇ! BİR DAHAKİNE DAHA DA İLERİ GİDEBİLİR MİSİNİZ?",
["İyi başlangıç, şimdi gerisini alın!"] = "İYİ BAŞLANGIÇ, ŞİMDİ GERİSİNİ ALIN!",
["İyi başlangıç, şimdi kalanını alın!"] = "İYİ BAŞLANGIÇ, ŞİMDİ KALANINI ALIN!",
["İyi bir adam olduğum için şanslısınız..."] = "İYİ BİR ADAM OLDUĞUM İÇİN ŞANSLISINIZ...",
["İyi bir amaç uğruna para yakmak her zaman uygundur. Düşmanlarını ezmek de çok iyi bir amaçtır."] = "İYİ BİR AMAÇ UĞRUNA PARA YAKMAK HER ZAMAN UYGUNDUR. DÜŞMANLARINI EZMEK DE ÇOK İYİ BİR AMAÇTIR.",
["İyi bir başlangıç."] = "İYİ BİR BAŞLANGIÇ.",
["İyi bir ekip, soyguna hem Mühimmat Çantaları hem de Doktor Çantaları getirir."] = "İYİ BİR EKİP, SOYGUNA HEM MÜHİMMAT ÇANTALARI HEM DE DOKTOR ÇANTALARI GETİRİR.",
["İyi bir formül buldunuz mu dostlar?"] = "İYİ BİR FORMÜL BULDUNUZ MU DOSTLAR?",
["İyi bir gösteri sun"] = "İYİ BİR GÖSTERİ SUN",
["İyi bir müzik olmadan soygun olur mu?"] = "İYİ BİR MÜZİK OLMADAN SOYGUN OLUR MU?",
["İyi bir soyguncu temel araçlarla idare etmeyi öğrenir. Süslü ek imkânlar kullanmadan işi yapabilirsen ödülün bir o kadar tatlı olur."] = "İYİ BİR SOYGUNCU TEMEL ARAÇLARLA İDARE ETMEYİ ÖĞRENİR. SÜSLÜ EK İMKÂNLAR KULLANMADAN İŞİ YAPABİLİRSEN ÖDÜLÜN BİR O KADAR TATLI OLUR.",
["İyi bir taktik oyunu, büyük soygundan önce hazırlanmanın en iyi yoludur. Dallas stratejik düşüncesini, zafer için birlik ve kaynak yönetmek gereken zor, hesaplı bir oyunla harekete geçirmeyi tercih eder."] = "İYİ BİR TAKTİK OYUNU, BÜYÜK SOYGUNDAN ÖNCE HAZIRLANMANIN EN İYİ YOLUDUR. DALLAS STRATEJİK DÜŞÜNCESİNİ, ZAFER İÇİN BİRLİK VE KAYNAK YÖNETMEK GEREKEN ZOR, HESAPLI BİR OYUNLA HAREKETE GEÇİRMEYİ TERCİH EDER.",
["İyi bir taktik yeleğe ve muharebe pantolonuna asla hayır deme. Bol cepli olsun. Asla fazla cep olmaz. Payday gang kariyerinin başlarında Chains, bu takımı oluşturmak, denemek, ayarlamak ve soygunda en iyi performansı vereceğinden emin olmak için neredeyse iki ay uğraştı. Bunca yıl sonra pek az değişti ve fiziksel açıdan zorlu soygunlarda hâlâ gözde kıyafetlerden biri."] = "İYİ BİR TAKTİK YELEĞE VE MUHAREBE PANTOLONUNA ASLA HAYIR DEME. BOL CEPLİ OLSUN. ASLA FAZLA CEP OLMAZ. PAYDAY GANG KARİYERİNİN BAŞLARINDA CHAINS, BU TAKIMI OLUŞTURMAK, DENEMEK, AYARLAMAK VE SOYGUNDA EN İYİ PERFORMANSI VERECEĞİNDEN EMİN OLMAK İÇİN NEREDEYSE İKİ AY UĞRAŞTI. BUNCA YIL SONRA PEK AZ DEĞİŞTİ VE FİZİKSEL AÇIDAN ZORLU SOYGUNLARDA HÂLÂ GÖZDE KIYAFETLERDEN BİRİ.",
["İyi bir yerde mevzi alın!"] = "İYİ BİR YERDE MEVZİ ALIN!",
["İyi bir şoför, her tahliye planının belkemiğidir. Buna göre yatırım yapmayı ihmal etmeyin."] = "İYİ BİR ŞOFÖR, HER TAHLİYE PLANININ BELKEMİĞİDİR. BUNA GÖRE YATIRIM YAPMAYI İHMAL ETMEYİN.",
["İyi buldunuz! Patlayıcıları rayların üzerinden geçen boru hattına yerleştirin. Uzaklaşınca patlatıp düşüreceğim, kaçış yolunu kapatacak."] = "İYİ BULDUNUZ! PATLAYICILARI RAYLARIN ÜZERİNDEN GEÇEN BORU HATTINA YERLEŞTİRİN. UZAKLAŞINCA PATLATIP DÜŞÜRECEĞİM, KAÇIŞ YOLUNU KAPATACAK.",
["İyi buldunuz, doğru parçanın üzerinde siyah renk var."] = "İYİ BULDUNUZ, DOĞRU PARÇANIN ÜZERİNDE SİYAH RENK VAR.",
["İyi buldunuz. Ama daha fazla C4 gerekecek. Aramaya devam edin."] = "İYİ BULDUNUZ. AMA DAHA FAZLA C4 GEREKECEK. ARAMAYA DEVAM EDİN.",
["İyi buldunuz. Bu Anahtar Kartı sizi vagonlara sokar. "] = "İYİ BULDUNUZ. BU ANAHTAR KARTI SİZİ VAGONLARA SOKAR. ",
["İyi buldunuz. Bu kesin iş görür."] = "İYİ BULDUNUZ. BU KESİN İŞ GÖRÜR.",
["İyi buldunuz. Bu sonra işe yarayacak."] = "İYİ BULDUNUZ. BU SONRA İŞE YARAYACAK.",
["İyi denge ve artırılmış isabet sağlamak üzere ergonomik tasarlanmıştır."] = "İYİ DENGE VE ARTIRILMIŞ İSABET SAĞLAMAK ÜZERE ERGONOMİK TASARLANMIŞTIR.",
["İyi değil, bunlar keskin nişancı!"] = "İYİ DEĞİL, BUNLAR KESKİN NİŞANCI!",
["İyi değil. Sistem kilidi devrede. Ana bilgisayara gidip sistemini kırmalısınız."] = "İYİ DEĞİL. SİSTEM KİLİDİ DEVREDE. ANA BİLGİSAYARA GİDİP SİSTEMİNİ KIRMALISINIZ.",
["İyi dinleyin. O kasaların her birini geri almanız gerekiyor. Beni hayal kırıklığına uğratamazsınız."] = "İYİ DİNLEYİN. O KASALARIN HER BİRİNİ GERİ ALMANIZ GEREKİYOR. BENİ HAYAL KIRIKLIĞINA UĞRATAMAZSINIZ.",
["İyi dostlarım, Vlad'in aile meselesinde biraz yardıma ihtiyacı var. Anlarsınız, ufak soygun."] = "İYİ DOSTLARIM, VLAD'İN AİLE MESELESİNDE BİRAZ YARDIMA İHTİYACI VAR. ANLARSINIZ, UFAK SOYGUN.",
["İyi düşündünüz dostlar. Şimdi güvenlik kapısını geçmelisiniz."] = "İYİ DÜŞÜNDÜNÜZ DOSTLAR. ŞİMDİ GÜVENLİK KAPISINI GEÇMELİSİNİZ.",
["İyi düşündünüz! Bütün kabloları keserseniz zemin yine güvenli olacak."] = "İYİ DÜŞÜNDÜNÜZ! BÜTÜN KABLOLARI KESERSENİZ ZEMİN YİNE GÜVENLİ OLACAK.",
["İyi düşündünüz! O tahtalarla daha fazla pencereye barikat kurun."] = "İYİ DÜŞÜNDÜNÜZ! O TAHTALARLA DAHA FAZLA PENCEREYE BARİKAT KURUN.",
["İyi düşündünüz! O tahtalarla daha fazla pencereyi kapatın."] = "İYİ DÜŞÜNDÜNÜZ! O TAHTALARLA DAHA FAZLA PENCEREYİ KAPATIN.",
["İyi düşündünüz! Oy makineleri Washington'daki alışveriş merkezine gidiyor. Oraya sevkiyat yapan şirketi bulmaya çalışın."] = "İYİ DÜŞÜNDÜNÜZ! OY MAKİNELERİ WASHINGTON'DAKİ ALIŞVERİŞ MERKEZİNE GİDİYOR. ORAYA SEVKİYAT YAPAN ŞİRKETİ BULMAYA ÇALIŞIN.",
["İyi düşündünüz! Silahları yok etmek için o ateşi kullanın."] = "İYİ DÜŞÜNDÜNÜZ! SİLAHLARI YOK ETMEK İÇİN O ATEŞİ KULLANIN.",
["İyi düşündünüz, tahtalar onları yavaşlatır."] = "İYİ DÜŞÜNDÜNÜZ, TAHTALAR ONLARI YAVAŞLATIR.",
["İyi düşündünüz."] = "İYİ DÜŞÜNDÜNÜZ.",
["İyi düşündünüz. Oy makineleri 6. bölgedeki AVM'ye gidiyor. O bölgeye sevkiyat yapan şirketi bulmaya çalışın."] = "İYİ DÜŞÜNDÜNÜZ. OY MAKİNELERİ 6. BÖLGEDEKİ AVM'YE GİDİYOR. O BÖLGEYE SEVKİYAT YAPAN ŞİRKETİ BULMAYA ÇALIŞIN.",
["İyi düşündünüz. Parayı buradan çıkarmak için onu kullanıyoruz."] = "İYİ DÜŞÜNDÜNÜZ. PARAYI BURADAN ÇIKARMAK İÇİN ONU KULLANIYORUZ.",
["İyi düşündünüz. Şimdi güvenlik kapısını aşıp sizi Kasa Dairesi'ne nasıl götüreceğimize bakalım."] = "İYİ DÜŞÜNDÜNÜZ. ŞİMDİ GÜVENLİK KAPISINI AŞIP SİZİ KASA DAİRESİ'NE NASIL GÖTÜRECEĞİMİZE BAKALIM.",
["İyi düşünülmüş bir planın faydasını gördünüz. Disiplininiz etkileyici. Kazancınızın tadını çıkarın. Uzmanlığınıza yeniden ihtiyacım olduğunda sizinle iletişime geçeceğim."] = "İYİ DÜŞÜNÜLMÜŞ BİR PLANIN FAYDASINI GÖRDÜNÜZ. DİSİPLİNİNİZ ETKİLEYİCİ. KAZANCINIZIN TADINI ÇIKARIN. UZMANLIĞINIZA YENİDEN İHTİYACIM OLDUĞUNDA SİZİNLE İLETİŞİME GEÇECEĞİM.",
["İyi düşünülmüş ve kararlılıkla uygulanmış bir planın ödülünü aldınız. Çok etkileyici. Size yeniden ihtiyacım olduğunda iletişime geçeceğim."] = "İYİ DÜŞÜNÜLMÜŞ VE KARARLILIKLA UYGULANMIŞ BİR PLANIN ÖDÜLÜNÜ ALDINIZ. ÇOK ETKİLEYİCİ. SİZE YENİDEN İHTİYACIM OLDUĞUNDA İLETİŞİME GEÇECEĞİM.",
["İyi fikir! Doğru ayarlarsanız o kamyon kapıyı yerinden söküp alır."] = "İYİ FİKİR! DOĞRU AYARLARSANIZ O KAMYON KAPIYI YERİNDEN SÖKÜP ALIR.",
["İyi geceler keskin nişancılar! İyi iş millet. Şimdi C4'ü alma vakti."] = "İYİ GECELER KESKİN NİŞANCILAR! İYİ İŞ MİLLET. ŞİMDİ C4'Ü ALMA VAKTİ.",
["İyi geceler."] = "İYİ GECELER.",
["İyi gidiyorsunuz dostlarım. Ama bu daha ilki. İkinci paleti bulun."] = "İYİ GİDİYORSUNUZ DOSTLARIM. AMA BU DAHA İLKİ. İKİNCİ PALETİ BULUN.",
["İyi gidiyorsunuz ekip. Çıkma vakti."] = "İYİ GİDİYORSUNUZ EKİP. ÇIKMA VAKTİ.",
["İyi gidiyorsunuz! Helikopter dönene kadar dayanın!"] = "İYİ GİDİYORSUNUZ! HELİKOPTER DÖNENE KADAR DAYANIN!",
["İyi gidiyorsunuz. Sadece bir renk-sayı takımı kaldı."] = "İYİ GİDİYORSUNUZ. SADECE BİR RENK-SAYI TAKIMI KALDI.",
["İyi gidiyoruz, muhafızlardan uzak durun."] = "İYİ GİDİYORUZ, MUHAFIZLARDAN UZAK DURUN.",
["İyi gidiyoruz... Bir şey fark etmediler..."] = "İYİ GİDİYORUZ... BİR ŞEY FARK ETMEDİLER...",
["İyi gidiyoruz... İyi gidiyoruz."] = "İYİ GİDİYORUZ... İYİ GİDİYORUZ.",
["İyi giriş noktası gişe kapısı gibi görünüyor. Testere kullanın."] = "İYİ GİRİŞ NOKTASI GİŞE KAPISI GİBİ GÖRÜNÜYOR. TESTERE KULLANIN.",
["İyi görünmek ve sıcak kalmak birbirini dışlamaz."] = "İYİ GÖRÜNMEK VE SICAK KALMAK BİRBİRİNİ DIŞLAMAZ.",
["İyi görünmüyor millet, hiç iyi görünmüyor!"] = "İYİ GÖRÜNMÜYOR MİLLET, HİÇ İYİ GÖRÜNMÜYOR!",
["İyi görünmüyor millet... İyi görünmüyor!"] = "İYİ GÖRÜNMÜYOR MİLLET... İYİ GÖRÜNMÜYOR!",
["İyi görünüyor! Şimdi vinç kontrolleriyle lokomotifimizi taşıyın. Bunun işe yarayacağından eminim! Şey, belki emin değilim ama çok iyimserim!"] = "İYİ GÖRÜNÜYOR! ŞİMDİ VİNÇ KONTROLLERİYLE LOKOMOTİFİMİZİ TAŞIYIN. BUNUN İŞE YARAYACAĞINDAN EMİNİM! ŞEY, BELKİ EMİN DEĞİLİM AMA ÇOK İYİMSERİM!",
["İyi görünüyor..."] = "İYİ GÖRÜNÜYOR...",
["İyi günler dostlar, bir daha asla görüşmemek üzere!"] = "İYİ GÜNLER DOSTLAR, BİR DAHA ASLA GÖRÜŞMEMEK ÜZERE!",
["İyi günler efendim."] = "İYİ GÜNLER EFENDİM.",
["İyi günler hanımefendi. Bugün size nasıl yardımcı olabilirim?"] = "İYİ GÜNLER HANIMEFENDİ. BUGÜN SİZE NASIL YARDIMCI OLABİLİRİM?",
["İyi günler, Müdür Stevens."] = "İYİ GÜNLER, MÜDÜR STEVENS.",
["İyi günler, dostlarım."] = "İYİ GÜNLER, DOSTLARIM.",
["İyi günler. Ben Randolph, bugün size yardımcı olacağım."] = "İYİ GÜNLER. BEN RANDOLPH, BUGÜN SİZE YARDIMCI OLACAĞIM.",
["İyi günler. Benevolent Bank. Ben Martin."] = "İYİ GÜNLER. BENEVOLENT BANK. BEN MARTİN.",
["İyi günler. Benevolent'a bağlandınız. Ben Martin."] = "İYİ GÜNLER. BENEVOLENT'A BAĞLANDINIZ. BEN MARTİN.",
["İyi günler. Burası Benevolent Bank. Ben Martin."] = "İYİ GÜNLER. BURASI BENEVOLENT BANK. BEN MARTİN.",
["İyi günler. Roberts Bank. Ben Randolph."] = "İYİ GÜNLER. ROBERTS BANK. BEN RANDOLPH.",
["İyi günler. Roberts bankası. Nasıl yardım edebilirim?"] = "İYİ GÜNLER. ROBERTS BANKASI. NASIL YARDIM EDEBİLİRİM?",
["İyi haber: Commissar'ın çatı katında KOCAMAN bir kokain zulası var. Kötü haber: Olabildiğince hızlı sifonu çekip döküyor. Tuvaletten aşağı servet dönüyor. Ne kadar hızlı varırsanız bonus o kadar büyük!"] = "İYİ HABER: COMMİSSAR'IN ÇATI KATINDA KOCAMAN BİR KOKAİN ZULASI VAR. KÖTÜ HABER: OLABİLDİĞİNCE HIZLI SİFONU ÇEKİP DÖKÜYOR. TUVALETTEN AŞAĞI SERVET DÖNÜYOR. NE KADAR HIZLI VARIRSANIZ BONUS O KADAR BÜYÜK!",
["İyi haberim de var, kötü haberim de. Kötü haber, arabam öldü. İyi haber, bagajdan birkaç elmas almaya vaktim oldu. Yakınlardaki bir depodalar."] = "İYİ HABERİM DE VAR, KÖTÜ HABERİM DE. KÖTÜ HABER, ARABAM ÖLDÜ. İYİ HABER, BAGAJDAN BİRKAÇ ELMAS ALMAYA VAKTİM OLDU. YAKINLARDAKİ BİR DEPODALAR.",
["İyi hamle."] = "İYİ HAMLE.",
["İyi hamle... Kesin depoya çıkar."] = "İYİ HAMLE... KESİN DEPOYA ÇIKAR.",
["İyi insanlar olduğunuz belli."] = "İYİ İNSANLAR OLDUĞUNUZ BELLİ.",
["İyi iş Dallas. Şimdi kokaini alıp minibüse dön. Buradaki işimiz bitti."] = "İYİ İŞ DALLAS. ŞİMDİ KOKAİNİ ALIP MİNİBÜSE DÖN. BURADAKİ İŞİMİZ BİTTİ.",
["İyi iş ama dördüncü kata biraz daha gerekiyor."] = "İYİ İŞ AMA DÖRDÜNCÜ KATA BİRAZ DAHA GEREKİYOR.",
["İyi iş beyler! Alın teriyle kazanılmış para!"] = "İYİ İŞ BEYLER! ALIN TERİYLE KAZANILMIŞ PARA!",
["İyi iş diyorum! Hahaha! Sizinle yine çalışacağım! Ah! Vlad lanet Sputnik gibi yükselişte! Hoh! Şimdi parti zamanı! Parti parti! Hey!"] = "İYİ İŞ DİYORUM! HAHAHA! SİZİNLE YİNE ÇALIŞACAĞIM! AH! VLAD LANET SPUTNİK GİBİ YÜKSELİŞTE! HOH! ŞİMDİ PARTİ ZAMANI! PARTİ PARTİ! HEY!",
["İyi iş dostlar ama henüz yarısındasınız. Boris'i takip edin. Sizi şehir dışındaki çiftliğe götürecek, orada... Bilirsiniz... Kokaini çıkarabilir. Onu koruyun."] = "İYİ İŞ DOSTLAR AMA HENÜZ YARISINDASINIZ. BORİS'İ TAKİP EDİN. SİZİ ŞEHİR DIŞINDAKİ ÇİFTLİĞE GÖTÜRECEK, ORADA... BİLİRSİNİZ... KOKAİNİ ÇIKARABİLİR. ONU KORUYUN.",
["İyi iş dostlar!"] = "İYİ İŞ DOSTLAR!",
["İyi iş dostlar, şimdi kaldırıp çıkarın."] = "İYİ İŞ DOSTLAR, ŞİMDİ KALDIRIP ÇIKARIN.",
["İyi iş dostlar. Almaya geldiğimizi aldık ama sonuncusu... Sonraki hamlemizi düşünmeliyiz. Siz depodan ayrılınca Murkywater iletişimi tamamen sustu, ağdan çıktılar. Kataru'ya iyi zarar verdik ama nasıl misilleme yapacaklarını bilmiyoruz. Bain, ona ne olursa olsun devam etmemizi isterdi. Duke bu bulmacanın sonraki parçasını ve o kutuların aslında ne işe yaradığını çözmekle epey meşgul olacak. O zamana kadar gizleneceğiz... plan yapacağız... hayatta kalacağız."] = "İYİ İŞ DOSTLAR. ALMAYA GELDİĞİMİZİ ALDIK AMA SONUNCUSU... SONRAKİ HAMLEMİZİ DÜŞÜNMELİYİZ. SİZ DEPODAN AYRILINCA MURKYWATER İLETİŞİMİ TAMAMEN SUSTU, AĞDAN ÇIKTILAR. KATARU'YA İYİ ZARAR VERDİK AMA NASIL MİSİLLEME YAPACAKLARINI BİLMİYORUZ. BAIN, ONA NE OLURSA OLSUN DEVAM ETMEMİZİ İSTERDİ. DUKE BU BULMACANIN SONRAKİ PARÇASINI VE O KUTULARIN ASLINDA NE İŞE YARADIĞINI ÇÖZMEKLE EPEY MEŞGUL OLACAK. O ZAMANA KADAR GİZLENECEĞİZ... PLAN YAPACAĞIZ... HAYATTA KALACAĞIZ.",
["İyi iş ekip ama NYPD o kadar kolay pes etmez."] = "İYİ İŞ EKİP AMA NYPD O KADAR KOLAY PES ETMEZ.",
["İyi iş ekip. Hector, bilgi için FBI'ı bastığımızı bilse biraz endişelenirdi. Ama Hector'ın bilmediği şey canını yakmaz. Hadi bankacılık yapalım mı?"] = "İYİ İŞ EKİP. HECTOR, BİLGİ İÇİN FBI'I BASTIĞIMIZI BİLSE BİRAZ ENDİŞELENİRDİ. AMA HECTOR'IN BİLMEDİĞİ ŞEY CANINI YAKMAZ. HADİ BANKACILIK YAPALIM MI?",
["İyi iş ekip. Merdivenden çıkıp oradan gidin."] = "İYİ İŞ EKİP. MERDİVENDEN ÇIKIP ORADAN GİDİN.",
["İyi iş ekip. Mikro kameralar tablolara yerleştirildiğine göre, artık bunları senatörün adamlarına vermemiz yeter. Görüşmeyi hemen ayarlıyorum."] = "İYİ İŞ EKİP. MİKRO KAMERALAR TABLOLARA YERLEŞTİRİLDİĞİNE GÖRE, ARTIK BUNLARI SENATÖRÜN ADAMLARINA VERMEMİZ YETER. GÖRÜŞMEYİ HEMEN AYARLIYORUM.",
["İyi iş ekip. Şimdi Bile'dan patlayıcı almamız gerekiyor. Biraz zaman verin. 'Bile, vakit geldi. C4'ü ne kadar sürede bırakabilirsin?'"] = "İYİ İŞ EKİP. ŞİMDİ BILE'DAN PATLAYICI ALMAMIZ GEREKİYOR. BİRAZ ZAMAN VERİN. 'BILE, VAKİT GELDİ. C4'Ü NE KADAR SÜREDE BIRAKABİLİRSİN?'",
["İyi iş ekip. Şimdi keçileri içeri taşımaya başlayın."] = "İYİ İŞ EKİP. ŞİMDİ KEÇİLERİ İÇERİ TAŞIMAYA BAŞLAYIN.",
["İyi iş millet! Doğru olan bu gibi! Bir an önce oradan çıksanız iyi olur."] = "İYİ İŞ MİLLET! DOĞRU OLAN BU GİBİ! BİR AN ÖNCE ORADAN ÇIKSANIZ İYİ OLUR.",
["İyi iş millet! Doğrusu bu gibi görünüyor! Bir an önce oradan çıksanız iyi olur. Bulduğunuz uçak anahtarlarını kullanın."] = "İYİ İŞ MİLLET! DOĞRUSU BU GİBİ GÖRÜNÜYOR! BİR AN ÖNCE ORADAN ÇIKSANIZ İYİ OLUR. BULDUĞUNUZ UÇAK ANAHTARLARINI KULLANIN.",
["İyi iş millet! Doğrusu bu gibi görünüyor! Sizi almaya geri dönüyorum!"] = "İYİ İŞ MİLLET! DOĞRUSU BU GİBİ GÖRÜNÜYOR! SİZİ ALMAYA GERİ DÖNÜYORUM!",
["İyi iş millet! Eliniz değmişken bana bir hamburger alın. Depoda görüşürüz!"] = "İYİ İŞ MİLLET! ELİNİZ DEĞMİŞKEN BANA BİR HAMBURGER ALIN. DEPODA GÖRÜŞÜRÜZ!",
["İyi iş millet."] = "İYİ İŞ MİLLET.",
["İyi iş millet. Bu, tarama odasındaki gazı temizler."] = "İYİ İŞ MİLLET. BU, TARAMA ODASINDAKİ GAZI TEMİZLER.",
["İyi iş millet. Hem sessiz kaldınız hem mesajı verdiniz. Paraları gitti. Vlad da onun ekibinden olduğunuzu onlara mutlaka söyleyecek."] = "İYİ İŞ MİLLET. HEM SESSİZ KALDINIZ HEM MESAJI VERDİNİZ. PARALARI GİTTİ. VLAD DA ONUN EKİBİNDEN OLDUĞUNUZU ONLARA MUTLAKA SÖYLEYECEK.",
["İyi iş millet. Kötü gidebilirdi ama kârda kalmamızı sağladınız. Silah ticaretine var mısınız?"] = "İYİ İŞ MİLLET. KÖTÜ GİDEBİLİRDİ AMA KÂRDA KALMAMIZI SAĞLADINIZ. SİLAH TİCARETİNE VAR MISINIZ?",
["İyi iş millet. Locke payımızı aktardı. Bu adamı henüz çözemedim ama bakalım işler nasıl gidecek."] = "İYİ İŞ MİLLET. LOCKE PAYIMIZI AKTARDI. BU ADAMI HENÜZ ÇÖZEMEDİM AMA BAKALIM İŞLER NASIL GİDECEK.",
["İyi iş millet. Sinsi, mesaj alındı. Ganimet gitti, Vlad de korkulan adamlar listesinde kesinlikle yükselecek."] = "İYİ İŞ MİLLET. SİNSİ, MESAJ ALINDI. GANİMET GİTTİ, VLAD DE KORKULAN ADAMLAR LİSTESİNDE KESİNLİKLE YÜKSELECEK.",
["İyi iş palyaçolar. Tekerleri döndürmeye devam edin."] = "İYİ İŞ PALYAÇOLAR. TEKERLERİ DÖNDÜRMEYE DEVAM EDİN.",
["İyi iş sevgili dostlarım. Hepinizi çok seviyorum lan. Bütün bu kokaini sevdiğim kadar değil ama yine de bayağı seviyorum!"] = "İYİ İŞ SEVGİLİ DOSTLARIM. HEPİNİZİ ÇOK SEVİYORUM LAN. BÜTÜN BU KOKAİNİ SEVDİĞİM KADAR DEĞİL AMA YİNE DE BAYAĞI SEVİYORUM!",
["İyi iş soyguncu! TP böyle kazanılır!"] = "İYİ İŞ SOYGUNCU! TP BÖYLE KAZANILIR!",
["İyi iş çocuklar."] = "İYİ İŞ ÇOCUKLAR.",
["İyi iş çocuklar. Bu işe başarı demeye yeter."] = "İYİ İŞ ÇOCUKLAR. BU İŞE BAŞARI DEMEYE YETER.",
["İyi iş çıkardın Dallas. Minibüs seni bekliyor."] = "İYİ İŞ ÇIKARDIN DALLAS. MİNİBÜS SENİ BEKLİYOR.",
["İyi iş çıkardın Dallas. Şimdi minibüse gidip oradan çık."] = "İYİ İŞ ÇIKARDIN DALLAS. ŞİMDİ MİNİBÜSE GİDİP ORADAN ÇIK.",
["İyi iş çıkardın. Dürüst olayım, beklediğimden iyi. Almaya geldiğimizi aldık. Çaldığın altından da iyi para kazanırız bence. Yeniden başlaman için fazlasıyla yeter."] = "İYİ İŞ ÇIKARDIN. DÜRÜST OLAYIM, BEKLEDİĞİMDEN İYİ. ALMAYA GELDİĞİMİZİ ALDIK. ÇALDIĞIN ALTINDAN DA İYİ PARA KAZANIRIZ BENCE. YENİDEN BAŞLAMAN İÇİN FAZLASIYLA YETER.",
["İyi iş çıkardın. Tankere bin."] = "İYİ İŞ ÇIKARDIN. TANKERE BİN.",
["İyi iş çıkardınız millet. Taşıması tam bir belaydı ama doğru motoru aldık ve sıkı sıkıya kilitledik. Belki bir gün kendi hesabımıza çalışıp onu geri alırız, ha?"] = "İYİ İŞ ÇIKARDINIZ MİLLET. TAŞIMASI TAM BİR BELAYDI AMA DOĞRU MOTORU ALDIK VE SIKI SIKIYA KİLİTLEDİK. BELKİ BİR GÜN KENDİ HESABIMIZA ÇALIŞIP ONU GERİ ALIRIZ, HA?",
["İyi iş çıkardınız, dostlar. İyi iş! Adamımızı geri aldık. Bain... eve döndü. Ama Murky'ler ona bir şey yapmış. Şu an uzmanlar muayene ediyor. Bir tür virüs olduğunu, belki de üretilmiş olabileceğini söylüyorlar. Ölürse... Ah, şu lanet Locke çok kızacak, Kataru'ya bunu ödetecek..."] = "İYİ İŞ ÇIKARDINIZ, DOSTLAR. İYİ İŞ! ADAMIMIZI GERİ ALDIK. BAIN... EVE DÖNDÜ. AMA MURKY'LER ONA BİR ŞEY YAPMIŞ. ŞU AN UZMANLAR MUAYENE EDİYOR. BİR TÜR VİRÜS OLDUĞUNU, BELKİ DE ÜRETİLMİŞ OLABİLECEĞİNİ SÖYLÜYORLAR. ÖLÜRSE... AH, ŞU LANET LOCKE ÇOK KIZACAK, KATARU'YA BUNU ÖDETECEK...",
["İyi iş çıkardınız, maskeli dostlarım. Biraz C4'e hazır mısınız?"] = "İYİ İŞ ÇIKARDINIZ, MASKELİ DOSTLARIM. BİRAZ C4'E HAZIR MISINIZ?",
["İyi iş!"] = "İYİ İŞ!",
["İyi iş! Altın zulalarından biri bu. Aramaya devam edin, bir tane daha olmalı."] = "İYİ İŞ! ALTIN ZULALARINDAN BİRİ BU. ARAMAYA DEVAM EDİN, BİR TANE DAHA OLMALI.",
["İyi iş! Artık sevkiyat programına erişebiliyoruz. İdari ofisten değiştirebiliriz."] = "İYİ İŞ! ARTIK SEVKİYAT PROGRAMINA ERİŞEBİLİYORUZ. İDARİ OFİSTEN DEĞİŞTİREBİLİRİZ.",
["İyi iş! Biz tamamen hazır olmadan o kalıplar hiçbir yere gitmiyor."] = "İYİ İŞ! BİZ TAMAMEN HAZIR OLMADAN O KALIPLAR HİÇBİR YERE GİTMİYOR.",
["İyi iş! Bu hediyeleri polislerden çok daha fazla hak ediyoruz. Bu yıl çok usluyduk!"] = "İYİ İŞ! BU HEDİYELERİ POLİSLERDEN ÇOK DAHA FAZLA HAK EDİYORUZ. BU YIL ÇOK USLUYDUK!",
["İyi iş! Devam edin."] = "İYİ İŞ! DEVAM EDİN.",
["İyi iş! Diski servis asansörüne koyun. Shayu'nun adamlarından biri sonra alacak."] = "İYİ İŞ! DİSKİ SERVİS ASANSÖRÜNE KOYUN. SHAYU'NUN ADAMLARINDAN BİRİ SONRA ALACAK.",
["İyi iş! Dokuzuncu dalga püskürtüldü!"] = "İYİ İŞ! DOKUZUNCU DALGA PÜSKÜRTÜLDÜ!",
["İyi iş! Fazladan ganimet bulmak beni hep mutlu eder."] = "İYİ İŞ! FAZLADAN GANİMET BULMAK BENİ HEP MUTLU EDER.",
["İyi iş! Hadi gidelim."] = "İYİ İŞ! HADİ GİDELİM.",
["İyi iş! Helikopter onu bırakıp geri kalanınızı almak için dönecek. Beklerken ormanda başka paketler arayın."] = "İYİ İŞ! HELİKOPTER ONU BIRAKIP GERİ KALANINIZI ALMAK İÇİN DÖNECEK. BEKLERKEN ORMANDA BAŞKA PAKETLER ARAYIN.",
["İyi iş! Hâlâ formunda olduğunu kanıtladın, Dallas."] = "İYİ İŞ! HÂLÂ FORMUNDA OLDUĞUNU KANITLADIN, DALLAS.",
["İyi iş! Kokaini minibüse atıp çık oradan!"] = "İYİ İŞ! KOKAİNİ MİNİBÜSE ATIP ÇIK ORADAN!",
["İyi iş! Metal dedektörü kapandı."] = "İYİ İŞ! METAL DEDEKTÖRÜ KAPANDI.",
["İyi iş! O kalıpları kaçış için işaretlediğimiz trene taşıyın."] = "İYİ İŞ! O KALIPLARI KAÇIŞ İÇİN İŞARETLEDİĞİMİZ TRENE TAŞIYIN.",
["İyi iş! Onuncu dalga püskürtüldü!"] = "İYİ İŞ! ONUNCU DALGA PÜSKÜRTÜLDÜ!",
["İyi iş! Payday Piggy hizmetiniz için teşekkür eder."] = "İYİ İŞ! PAYDAY PİGGY HİZMETİNİZ İÇİN TEŞEKKÜR EDER.",
["İyi iş! Payday Piggy hizmetleriniz için teşekkür ediyor."] = "İYİ İŞ! PAYDAY PİGGY HİZMETLERİNİZ İÇİN TEŞEKKÜR EDİYOR.",
["İyi iş! Pişirmeye dönün. Dalgalar arasındaki zamanı daha fazla malzeme bulmak için kullanın."] = "İYİ İŞ! PİŞİRMEYE DÖNÜN. DALGALAR ARASINDAKİ ZAMANI DAHA FAZLA MALZEME BULMAK İÇİN KULLANIN.",
["İyi iş! Prototipi otoparktaki minibüsümüze getirin. Bunu hak ettik be."] = "İYİ İŞ! PROTOTİPİ OTOPARKTAKİ MİNİBÜSÜMÜZE GETİRİN. BUNU HAK ETTİK BE.",
}
